/**
 * Cloudflare Worker — Regional Income Model API
 *
 * Endpoints:
 *   GET  /api/health
 *   GET  /api/model/summary
 *   GET  /api/model/betas
 *   GET  /api/model/states     ?sort=mean|state  &order=asc|desc
 *   GET  /api/model/years
 *   GET  /api/zips/search      ?q=PREFIX&year=YYYY
 *   POST /api/predict          { zip, year }
 *   GET  /api/audit-log        ?limit=N
 *   GET  /api/audit-log/stats
 *
 * Data files are generated by ../prepare_data.py
 */

import { Hono } from "hono";
import { cors } from "hono/cors";
import modelDataRaw from "./data/model_data.json";
import zipFeaturesRaw from "./data/zip_features.json";

// ── Types ─────────────────────────────────────────────────────────────────────

interface GlobalParam {
  mean: number;
  sd: number;
  hdi_3: number;
  hdi_97: number;
  r_hat?: number;
}

interface BetaEntry {
  feature: string;
  mean: number;
  sd: number;
  hdi_3: number;
  hdi_97: number;
  r_hat: number;
}

interface StateEntry {
  state: string;
  mean: number;
  sd: number;
  hdi_3: number;
  hdi_97: number;
}

interface YearEntry {
  year: number;
  mean: number;
  sd: number;
  hdi_3: number;
  hdi_97: number;
}

interface ModelData {
  alpha: GlobalParam;
  sigmaState: GlobalParam;
  sigmaYear: GlobalParam;
  sigmaObs: GlobalParam;
  betas: BetaEntry[];
  states: StateEntry[];
  years: YearEntry[];
  featureNames: string[];
  featureStats: { mean: number[]; std: number[] };
  fitMetrics: { r2: number; rmse: number; mae: number; gini_residuals: number };
  nPosteriorDraws: number;
  nTrainingZips: number;
  yearRange: [number, number];
  auditLog: unknown[];
  generatedAt?: string;
}

interface ZipEntry {
  state: string;
  features: number[];
  avg_income: number;
}

interface PredictionRecord {
  event: string;
  query: { zip: string; year: number; state: string };
  predicted: { income_mean: number; income_lo: number; income_hi: number; log_income_mean: number };
  decomposition: { alpha: number; beta_dot_x: number; state_effect: number; year_effect: number };
  feature_vector: Record<string, number>;
  actual_avg_income: number;
  timestamp: string;
}

// ── Data ──────────────────────────────────────────────────────────────────────

const modelData = modelDataRaw as unknown as ModelData;
const zipFeatures = zipFeaturesRaw as unknown as Record<string, ZipEntry>;

// In-memory prediction log (seeds from audit log, grows with web predictions)
const predictionLog: PredictionRecord[] = (modelData.auditLog ?? [])
  .slice(-50)
  .map((e: unknown) => {
    const entry = e as Record<string, unknown>;
    return {
      event: String(entry.event ?? "cli_prediction"),
      query: entry.query as PredictionRecord["query"],
      predicted: (entry.predicted ?? { income_mean: 0, income_lo: 0, income_hi: 0, log_income_mean: 0 }) as PredictionRecord["predicted"],
      decomposition: (entry.decomposition_posterior_mean ?? entry.decomposition ?? { alpha: 0, beta_dot_x: 0, state_effect: 0, year_effect: 0 }) as PredictionRecord["decomposition"],
      feature_vector: (entry.feature_vector_used ?? entry.feature_vector ?? {}) as Record<string, number>,
      actual_avg_income: Number(entry.actual_avg_income ?? 0),
      timestamp: String(entry.timestamp_utc ?? entry.timestamp ?? new Date().toISOString()),
    };
  });

// ── App ───────────────────────────────────────────────────────────────────────

const app = new Hono();

app.use(
  "*",
  cors({
    origin: "*",
    allowMethods: ["GET", "POST", "OPTIONS"],
    allowHeaders: ["Content-Type", "Authorization"],
  })
);

// ── Health ────────────────────────────────────────────────────────────────────

app.get("/api/health", (c) =>
  c.json({
    status: "ok",
    model: "Hierarchical Bayesian Panel Regression",
    version: "1.0.0",
    features: modelData.featureNames?.length ?? 0,
    posterior_draws: modelData.nPosteriorDraws,
    zip_year_pairs: Object.keys(zipFeatures).length,
    data_generated_at: modelData.generatedAt ?? null,
    timestamp: new Date().toISOString(),
  })
);

// ── Model summary ─────────────────────────────────────────────────────────────

app.get("/api/model/summary", (c) =>
  c.json({
    alpha: modelData.alpha,
    sigmaState: modelData.sigmaState,
    sigmaYear: modelData.sigmaYear,
    sigmaObs: modelData.sigmaObs,
    fitMetrics: modelData.fitMetrics,
    featureNames: modelData.featureNames,
    nPosteriorDraws: modelData.nPosteriorDraws,
    nTrainingZips: modelData.nTrainingZips,
    yearRange: modelData.yearRange,
    generatedAt: modelData.generatedAt ?? null,
  })
);

// ── Betas ─────────────────────────────────────────────────────────────────────

app.get("/api/model/betas", (c) =>
  c.json({
    betas: modelData.betas ?? [],
    featureNames: modelData.featureNames ?? [],
  })
);

// ── States ────────────────────────────────────────────────────────────────────

app.get("/api/model/states", (c) => {
  const sort  = c.req.query("sort")  ?? "mean";
  const order = c.req.query("order") ?? "desc";

  const sorted = [...(modelData.states ?? [])].sort((a, b) => {
    if (sort === "state") {
      const cmp = a.state.localeCompare(b.state);
      return order === "asc" ? cmp : -cmp;
    }
    return order === "asc" ? a.mean - b.mean : b.mean - a.mean;
  });

  return c.json({ states: sorted, count: sorted.length });
});

// ── Years ─────────────────────────────────────────────────────────────────────

app.get("/api/model/years", (c) =>
  c.json({ years: [...(modelData.years ?? [])].sort((a, b) => a.year - b.year) })
);

// ── ZIP search ────────────────────────────────────────────────────────────────

app.get("/api/zips/search", (c) => {
  const raw  = c.req.query("q") ?? "";
  const year = parseInt(c.req.query("year") ?? "2019", 10);

  // Pad partial zip prefix with leading zeros
  const prefix = raw.replace(/\D/g, "").padStart(Math.min(raw.replace(/\D/g, "").length, 5), "0");
  const suffix = `_${year}`;

  const results: { zip: string; state: string; avg_income: number }[] = [];

  for (const key of Object.keys(zipFeatures)) {
    if (results.length >= 30) break;
    if (!key.endsWith(suffix)) continue;
    const zip = key.slice(0, 5);
    if (prefix && !zip.startsWith(prefix)) continue;
    const entry = zipFeatures[key];
    results.push({ zip, state: entry.state, avg_income: entry.avg_income });
  }

  return c.json({ results, query: raw, year });
});

// ── Predict ───────────────────────────────────────────────────────────────────

app.post("/api/predict", async (c) => {
  let body: { zip?: string | number; year?: string | number };

  try {
    body = await c.req.json<{ zip?: string | number; year?: string | number }>();
  } catch {
    return c.json({ error: "Invalid JSON body" }, 400);
  }

  if (!body.zip || !body.year) {
    return c.json({ error: "Both zip and year are required" }, 400);
  }

  const zipRaw   = String(body.zip).replace(/\D/g, "");
  const zipPadded = zipRaw.padStart(5, "0");
  const yearInt  = parseInt(String(body.year), 10);

  if (zipPadded.length !== 5 || !/^\d{5}$/.test(zipPadded)) {
    return c.json({ error: "ZIP code must be exactly 5 digits" }, 400);
  }

  if (yearInt < 2011 || yearInt > 2022) {
    return c.json({ error: "Year must be between 2011 and 2022" }, 400);
  }

  const key   = `${zipPadded}_${yearInt}`;
  const entry = zipFeatures[key];

  if (!entry) {
    // Try nearest available year for this ZIP
    const fallbackYears = [2019, 2020, 2021, 2018, 2022, 2017, 2016, 2015, 2014, 2013, 2012, 2011];
    let fallbackKey: string | null = null;
    let fallbackYear: number | null = null;
    for (const fy of fallbackYears) {
      const fk = `${zipPadded}_${fy}`;
      if (zipFeatures[fk]) { fallbackKey = fk; fallbackYear = fy; break; }
    }

    if (!fallbackKey || !fallbackYear) {
      return c.json(
        {
          error: `ZIP ${zipPadded} is not in the training dataset`,
          hint: "The model was trained on ~3,000 stratified ZIPs. Try: 10001 (NY), 60601 (IL), 90210 (CA), 77001 (TX), 02101 (MA), 30301 (GA)",
        },
        404
      );
    }

    return c.json(
      {
        error: `ZIP ${zipPadded} exists but year ${yearInt} is unavailable — nearest year ${fallbackYear} found`,
        fallback_year: fallbackYear,
        fallback_key: fallbackKey,
        hint: `Re-submit with year=${fallbackYear} to get a result`,
      },
      404
    );
  }

  const { mean: xMean, std: xStd } = modelData.featureStats;
  const X_std = entry.features.map((v, i) => (v - xMean[i]) / (xStd[i] || 1));

  const alpha      = modelData.alpha.mean;
  const beta_dot_x = (modelData.betas ?? []).reduce<number>(
    (sum, b, i) => sum + b.mean * (X_std[i] ?? 0), 0
  );
  const stateEntry = (modelData.states ?? []).find((s) => s.state === entry.state);
  const yearEntry  = (modelData.years  ?? []).find((y) => y.year  === yearInt);

  const state_effect = stateEntry?.mean ?? 0;
  const year_effect  = yearEntry?.mean  ?? 0;

  const mu          = alpha + beta_dot_x + state_effect + year_effect;
  const income_mean = Math.exp(mu) - 1;

  // Approximate 94% CI propagation via sigma_obs
  const sigma_obs = modelData.sigmaObs?.mean ?? 0.232;
  const z94       = 1.88; // ~94% normal interval
  const income_lo = Math.exp(mu - z94 * sigma_obs) - 1;
  const income_hi = Math.exp(mu + z94 * sigma_obs) - 1;

  const featureVector: Record<string, number> = {};
  (modelData.featureNames ?? []).forEach((name, i) => {
    featureVector[name] = entry.features[i] ?? 0;
  });

  const result: PredictionRecord = {
    event: "web_prediction",
    query: { zip: zipPadded, year: yearInt, state: entry.state },
    predicted: { income_mean, income_lo, income_hi, log_income_mean: mu },
    decomposition: { alpha, beta_dot_x, state_effect, year_effect },
    feature_vector: featureVector,
    actual_avg_income: entry.avg_income,
    timestamp: new Date().toISOString(),
  };

  predictionLog.push(result);
  if (predictionLog.length > 500) predictionLog.shift();

  return c.json(result);
});

// ── Audit log ─────────────────────────────────────────────────────────────────

app.get("/api/audit-log", (c) => {
  const limit   = Math.min(parseInt(c.req.query("limit") ?? "50", 10), 200);
  const entries = predictionLog.slice(-limit).reverse();
  return c.json({ entries, total: predictionLog.length });
});

app.get("/api/audit-log/stats", (c) => {
  const byState: Record<string, number> = {};
  const byYear:  Record<number, number> = {};

  predictionLog.forEach((e) => {
    if (e.query?.state) byState[e.query.state] = (byState[e.query.state] ?? 0) + 1;
    if (e.query?.year)  byYear[e.query.year]   = (byYear[e.query.year]   ?? 0) + 1;
  });

  return c.json({
    total:   predictionLog.length,
    byState,
    byYear,
  });
});

export default app;
